export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text by uppercasing, lowercasing, or slugifying.',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'The text to transform.' },
          mode: { type: 'string', enum: ['uppercase', 'lowercase', 'slug'], description: 'Transform mode.' },
          trim: { type: 'boolean', default: true, description: 'Whether to trim surrounding whitespace (default true).' }
        },
        required: ['text', 'mode'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error('Unknown tool: ' + name);
  }
  // validate
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const { text, mode, trim = true } = args;
  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }
  if (mode !== 'uppercase' && mode !== 'lowercase' && mode !== 'slug') {
    throw new Error('mode must be uppercase, lowercase, or slug');
  }
  if (trim !== undefined && typeof trim !== 'boolean') {
    throw new Error('trim must be a boolean');
  }
  // check extra properties
  const allowed = new Set(['text', 'mode', 'trim']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Unexpected property: ' + key);
    }
  }

  let result;
  if (mode === 'uppercase') {
    result = trim ? text.trim() : text;
    result = result.toUpperCase();
  } else if (mode === 'lowercase') {
    result = trim ? text.trim() : text;
    result = result.toLowerCase();
  } else {
    // slug
    result = text.toLowerCase().trim();
    result = result.replace(/[^a-z0-9]+/g, '-');
    result = result.replace(/^-+|-+$/g, '');
  }

  return { content: [{ type: 'text', text: result }] };
}
